	@Test
	void crossOriginFormCannotExecuteSparqlUpdate() throws Exception {
		int status = postUpdate("https://attacker.example", "cross-site", false,
				"INSERT DATA { <urn:blocked> <urn:p> <urn:o> }");

		assertEquals(HttpURLConnection.HTTP_FORBIDDEN, status);
		assertEquals(0, repositorySize());
	}

	@Test
	void sameOriginAndExplicitlyPreflightedApiUpdatesRemainSupported() throws Exception {
		URI serverUri = URI.create(TestServer.SERVER_URL);
		String sameOrigin = serverUri.getScheme() + "://" + serverUri.getAuthority();

		int sameOriginStatus = postUpdate(sameOrigin, "same-origin", false,
				"INSERT DATA { <urn:same-origin> <urn:p> <urn:o> }");
		assertTrue(sameOriginStatus >= 200 && sameOriginStatus < 300);

		int explicitCorsStatus = postUpdate("https://client.example", "cross-site", true,
				"INSERT DATA { <urn:explicit-cors> <urn:p> <urn:o> }");
		assertTrue(explicitCorsStatus >= 200 && explicitCorsStatus < 300);
		assertEquals(2, repositorySize());
	}

